def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if not swapped:
            break

# 1. Introduced a swapped flag to optimize the algorithm.
# 2. If no two elements were swapped in the inner loop, the array is sorted.
