        self.nums = nums

    def sort(self):
        for i in range(len(self.nums)):
            for j in range(i+1, len(self.nums)):
                if self.nums[i] > self.nums[j]:
                    temp = self.nums[i]
                    self.nums[i] = self.nums[j]
                    self.nums[j] = temp
