def quick_sort(arr):
 if len(arr) == 0:
 return arr

 pivot = arr[len(arr) // 2]
 left_arr, right_arr = [], []

 for i in range(len(arr)):
 if arr[i] < pivot:
 left_arr.append(arr[i])
 elif arr[i] > pivot:
 right_arr.append(arr[i])

 return quick_sort(left_arr) + [pivot] + quick_sort(right_arr)
