def isAnagram(str1, str2): 
    str1 = str1.replace(" ", "").lower()
    str2 = str2.replace(" ", "").lower()

    # edge case
    if len(str1) != len(str2):
        return False

    count = {}
    for char in str1:
        if char in count:
            count[char] += 1
        else:
            count[char] = 1

    for char in str2:
        if char in count:
            count[char] -= 1
        else:
            count[char] = 1

    for val in count.values():
        if val != 0:
            return False
    return True

