def matrix_min_cost_path(matrix):
 n = len(matrix)
 m = len(matrix[0])

 min_cost = [[0 for i in range(m + 1)] for j in range(n + 1)] 

 for i in range(1, n + 1): 
  for j in range(1, m + 1): 
   if i == 1 and j == 1: 
    min_cost[i][j] = matrix[i-1][j-1]
   else: 
    min_cost[i][j] = matrix[i-1][j-1] + min(min_cost[i][j-1], min_cost[i-1][j], min_cost[i-1][j-1]) 

 return min_cost[n][m]
