def max_nested_depth(dictionary):
    max_depth = 0
    stack = []
    stack.append((dictionary, 1))

    while len(stack) > 0:
        item, depth = stack.pop()
        if depth > max_depth:
            max_depth = depth
        if type(item) is dict:
            for value in item.values():
                stack.append((value, depth+1))

    return max_depth

print(max_nested_depth(dictionary))
