def find_max_product(arr):
    if len(arr) == 0:
        return 0
    max_pos_1 = float("-inf")
    max_pos_2 = float("-inf")
    max_neg_1 = float("inf")
    max_neg_2 = float("inf")
    for num in arr:
        if num > max_pos_1:
            max_pos_2 = max_pos_1
            max_pos_1 = num
        elif num > max_pos_2:
            max_pos_2 = num

        if num < max_neg_1:
            max_neg_2 = max_neg_1
            max_neg_1 = num
        elif num < max_neg_2:
            max_neg_2 = num
    max_product = max((max_pos_1 * max_pos_2),(max_neg_1 * max_neg_2))
    return max_product

