def countPrimes(num): 
    if num <= 1:  
        return 0

    primes = [2] 
    x = 3

    while x <= num: 
        for y in primes: 
            if x % y == 0: 
                x += 2
                continue
        primes.append(x) 
        x += 2

    return len(primes) 

