def get_min_max_mode(numbers):
    min_val = min(numbers)
    max_val = max(numbers)

    count_dict = dict()
    for number in numbers:
        if number in count_dict:
            count_dict[number] += 1
        else:
            count_dict[number] = 1

    max_count = 0
    mode_value = min_val
    for k, v in count_dict.items():
        if v > max_count:
            max_count = v
            mode_value = k

    return min_val, max_val, mode_value

