    self.x = x
    self.y = y
    self.z = z

  def __add__(self, other): 
    x = self.x + other.x 
    y = self.y + other.y 
    z = self.z + other.z 
    return Vector(x, y, z) 

  def __sub__(self, other): 
    x = self.x - other.x 
    y = self.y - other.y 
    z = self.z - other.z 
    return Vector(x, y, z) 

  def __mul__(self, other): 
    x = self.x * other.x 
    y = self.y * other.y 
    z = self.z * other.z 
    return Vector(x, y, z) 

  def __div__(self, other): 
    x = self.x / other.x 
    y = self.y / other.y 
    z = self.z / other.z 
    return Vector(x, y, z) 

  def __str__(self): 
    return "Vector({}, {}, {})".format(self.x, self.y, self.z)
