        self.data = data 
        self.next = None
        self.prev = None

class Doubly_Linked_List: 

    def __init__(self): 
        self.head = None

    def insert(self, data): 
        new_node = Node(data) 
        if not self.head: 
            self.head = new_node 
        else: 
            new_node.next = self.head 
            self.head.prev = new_node 
            self.head = new_node

    def delete(self, del_node): 
        if not self.head: 
            return None
        if self.head == del_node: 
            self.head = self.head.next
            self.head.prev = None
        elif del_node.next: 
            del_node.next.prev = del_node.prev 
            del_node.prev.next = del_node.next 
        else: 
            del_node.prev.next = None
