def incrementally_process_data(stream, num_nodes):
  # validate number of nodes
  if num_nodes > MAX_NODES:
    return

  # create nodes
  nodes = []
  for _ in range(num_nodes):
    nodes.append(mp.Process(target=process_data, args=(data,)))

  # start nodes
  for node in nodes:
    node.start()

  # process stream
  for chunk in stream:
    for node in nodes:
      node.send(chunk)

  # join nodes
  for node in nodes:
    node.join()
