def get_prime_numbers(n):
    prime_numbers = []
    is_prime = [True]*(n+1)
    for i in range(2, n+1):
        if is_prime[i] == True:
            prime_numbers.append(i)
            for j in range(i, n+1, i):
                is_prime[j] = False
    return prime_numbers
